import gurobipy as gp
from gurobipy import GRB
products = []
values = {}
weights = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        pname = rec['values']['ProductName']
        products.append(pname)
        try:
            values[pname] = int(rec['values']['Value'])
            weights[pname] = int(rec['values']['Weight'])
        except Exception as e:
            raise ValueError(f'Missing or invalid Value/Weight for {pname}: {e}')
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv':
        try:
            capacity = int(rec['values']['Capacity'])
        except Exception as e:
            raise ValueError(f'Missing or invalid Capacity: {e}')
if capacity is None:
    raise ValueError('No capacity found in LEGACY_RECORDS.')
for pname in products:
    if pname not in values or pname not in weights:
        raise ValueError(f'Missing value or weight for product {pname}')
m = gp.Model('Vehicle_Inventory_Optimization')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weights[i] * x[i] for i in products)) <= capacity, name='inventory_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')